Lego Walk Scene 01 – Collider and OnMouseDown to turn Animator on and off
using UnityEngine;
using System.Collections;

public class AnimatorEnable : MonoBehaviour {

    public Animator anim;

    // Use this for initialization
    void Start()
    {
        anim = GetComponent<Animator>();
        anim.enabled = false;
}

    public void OnMouseDown()
    {
        anim.enabled = !anim.enabled; //for 1. Mouse Down Collider Animator simple
    }
}

