// This finds the game object by name rather than dragging into exposed variable box to wire up;
using UnityEngine;
using System.Collections;

public class InteractionScale : MonoBehaviour {
    GameObject legoMinifig;
    // Use this for initialization
    void Start()
    {
        legoMinifig = GameObject.FindWithTag("Lego");
    }
    public void OnMouseDown()
    {
        legoMinifig.GetComponent<AnimatorEnable>().ScaleLego();
}
}
